\begin{aligned}
\operatorname{IsTopSpace}(T)\leftrightarrow{}&\exists X\in\mathcal U\ \exists\tau\subseteq\mathcal P(X)\ \bigl(T=(X,\tau)\land\varnothing\in\tau\land X\in\tau\\
&\land\forall\mathcal A\subseteq\tau\ (\bigcup\mathcal A\in\tau)\land\forall U,V\in\tau\ (U\cap V\in\tau)\bigr),\\
\operatorname{Cts}(f,T,S)\leftrightarrow{}&\operatorname{IsTopSpace}(T)\land\operatorname{IsTopSpace}(S)\land f:X\to Y\land\forall V\in\sigma\ (f^{-1}[V]\in\tau),\\
\operatorname{Homeo}(f,T,S)\leftrightarrow{}&\operatorname{Cts}(f,T,S)\land\exists g:Y\to X\ (\operatorname{Cts}(g,S,T)\land g\circ f=1_X\land f\circ g=1_Y).
\end{aligned}
